settings.custom_liquid:
{% if collection.metafields.custom.texte_de_referencement != blank %}
  <div class="collection-read-more">
    <div class="collection-desc-text">
      {{ collection.metafields.custom.texte_de_referencement }}

      {% if collection.metafields.custom.texte_de_referencement_plus != blank %}
        <div class="collection-desc-more-content">
          {{ collection.metafields.custom.texte_de_referencement_plus }}
        </div>
      {% endif %}
    </div>

    {% if collection.metafields.custom.texte_de_referencement_plus != blank %}
      <button class="collection-read-more-btn">Lire plus</button>
    {% endif %}
  </div>
{% endif %}

<script>
  document.querySelectorAll('.collection-read-more-btn').forEach(btn => {
    btn.addEventListener('click', function () {
      const moreContent = this.previousElementSibling.querySelector('.collection-desc-more-content');
      const isExpanded = moreContent.classList.toggle('expanded');
      this.textContent = isExpanded ? 'Lire moins' : 'Lire plus';
    });
  });
</script>
